213	    [WinGetSource] Get()
214	    {
215	        if ([String]::IsNullOrWhiteSpace($this.Name))
216	        {
217	            throw "A value must be provided for WinGetSource::Name"
218	        }
219	
220	        $currentSource = $null
221	
222	        try {
223	            $currentSource = Get-WinGetSource -Name $this.Name
224	        }
225	        catch {
226	        }
227	
228	        $result = [WinGetSource]::new()
229	
230	        if ($currentSource)
231	        {
232	            $result.Ensure = [WinGetEnsure]::Present
233	            $result.Name = $currentSource.Name
234	            $result.Argument = $currentSource.Argument
235	            $result.Type = $currentSource.Type
236	            $result.TrustLevel = $currentSource.TrustLevel
237	            $result.Explicit = $currentSource.Explicit
238	            $result.Priority = $currentSource.Priority
239	        }
240	        else
241	        {
242	            $result.Ensure = [WinGetEnsure]::Absent
243	            $result.Name = $this.Name
244	        }
245	
246	        return $result
247	    }
