330	    # Test $this against a value retrieved from Get
331	    # We don't need to check Name because it is the Key for Get
332	    [bool] hidden TestAgainstCurrent([WinGetSource]$currentSource)
333	    {
334	        if ($this.Ensure -eq [WinGetEnsure]::Absent -and
335	            $currentSource.Ensure -eq [WinGetEnsure]::Absent)
336	        {
337	            return $true
338	        }
339	
340	        if ($this.Ensure -ne $currentSource.Ensure -or
341	            $this.Argument -ne $currentSource.Argument)
342	        {
343	            return $false
344	        }
345	
346	        if (-not([string]::IsNullOrWhiteSpace($this.Type)) -and
347	            $this.Type -ne $currentSource.Type)
348	        {
349	            return $false
350	        }
351	
352	        if ($this.TrustLevel -ne [WinGetTrustLevel]::Undefined -and
353	            $this.TrustLevel -ne $currentSource.TrustLevel)
354	        {
355	            return $false
356	        }
357	
358	        if ($null -ne $this.Explicit -and
359	            $this.Explicit -ne $currentSource.Explicit)
360	        {
361	            return $false
362	        }
363	
364	        if ($null -ne $this.Priority -and
365	            $this.Priority -ne $currentSource.Priority)
366	        {
367	            return $false
368	        }
369	
370	        return $true
371	    }
372	}
